// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IUniswapV3Pool} from "../interfaces/IUniswapV3.sol";
import {ITWAPOracle} from "../interfaces/ICoreInterfaces.sol";
import {TickMath, FullMath} from "../libraries/UniswapMath.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title TWAPOracle
 * @notice 基于Uniswap V3的时间加权平均价格预言机
 * @dev 读取V3池的observe()获取TWAP，防止瞬时价格操纵
 */
contract TWAPOracle is ITWAPOracle, Ownable {
    /// @notice V3预言机池（使用0.30%费率池，流动性最深）
    IUniswapV3Pool public immutable ORACLE_POOL;

    /// @notice WETH地址
    address public immutable override WETH;

    /// @notice USDC地址
    address public immutable override USDC;

    /// @notice 治理合约地址（可更新TWAP窗口）
    address public governance;

    /// @notice TWAP采样窗口（秒）
    uint32 public override twapWindow;

    /// @notice 默认TWAP窗口：30分钟
    uint32 public constant DEFAULT_TWAP_WINDOW = 1800;

    /// @notice 最小TWAP窗口：5分钟
    uint32 public constant MIN_TWAP_WINDOW = 300;

    /// @notice 最大TWAP窗口：24小时
    uint32 public constant MAX_TWAP_WINDOW = 86400;

    event TWAPWindowUpdated(uint32 oldWindow, uint32 newWindow);
    event GovernanceUpdated(address oldGovernance, address newGovernance);

    modifier onlyGovernance() {
        require(msg.sender == governance || msg.sender == owner(), "TWAPOracle: not authorized");
        _;
    }

    constructor(
        address _oraclePool,
        address _weth,
        address _usdc,
        address _governance
    ) Ownable(msg.sender) {
        require(_oraclePool != address(0), "TWAPOracle: zero pool");
        require(_weth != address(0), "TWAPOracle: zero WETH");
        require(_usdc != address(0), "TWAPOracle: zero USDC");

        ORACLE_POOL = IUniswapV3Pool(_oraclePool);
        WETH = _weth;
        USDC = _usdc;
        governance = _governance;
        twapWindow = DEFAULT_TWAP_WINDOW;

        // 验证池的token匹配
        address token0 = IUniswapV3Pool(_oraclePool).token0();
        address token1 = IUniswapV3Pool(_oraclePool).token1();
        require(
            (token0 == _weth && token1 == _usdc) || (token0 == _usdc && token1 == _weth),
            "TWAPOracle: pool tokens mismatch"
        );
    }

    /// @notice 获取TWAP价格和当前tick
    /// @return sqrtPriceX96Twap 时间加权均价 (sqrt(price) * 2^96)
    /// @return tick 算术平均tick
    function getTWAPPrice() public view override returns (uint160 sqrtPriceX96Twap, int24 tick) {
        uint32 window = twapWindow;
        uint32[] memory secondsAgos = new uint32[](2);
        secondsAgos[0] = window;
        secondsAgos[1] = 0;

        // observe返回tickCumulatives
        (int56[] memory tickCumulatives, ) = ORACLE_POOL.observe(secondsAgos);

        // 计算时间加权平均tick
        int56 tickCumulativesDelta = tickCumulatives[1] - tickCumulatives[0];
        int24 arithmeticMeanTick = int24(tickCumulativesDelta / int56(uint56(window)));

        // 向下取整处理负数
        if (tickCumulativesDelta < 0 && (tickCumulativesDelta % int56(uint56(window)) != 0)) {
            arithmeticMeanTick--;
        }

        tick = arithmeticMeanTick;
        sqrtPriceX96Twap = TickMath.getSqrtRatioAtTick(arithmeticMeanTick);
    }

    /// @notice 获取当前即时价格（非TWAP，仅用于参考）
    function getCurrentPrice() external view returns (uint160 sqrtPriceX96Spot, int24 tick) {
        (sqrtPriceX96Spot, tick, , , , , ) = ORACLE_POOL.slot0();
    }

    /// @notice 按TWAP价格换算代币数量
    /// @param amount 输入数量
    /// @param isWETHToUSDC true=WETH->USDC, false=USDC->WETH
    function quote(uint256 amount, bool isWETHToUSDC)
        external
        view
        override
        returns (uint256)
    {
        (uint160 sqrtPriceX96Twap, ) = getTWAPPrice();

        // 确定token0/token1顺序
        bool wethIsToken0 = ORACLE_POOL.token0() == WETH;

        // sqrtPriceX96 = sqrt(price) * 2^96
        // price = (sqrtPriceX96 / 2^96)^2 = sqrtPriceX96^2 / 2^192
        // price 表示 token1/token0 的比率（以最小单位计）
        // 注意：price已经包含了精度差，不需要额外乘除1e12

        uint256 priceSquared = uint256(sqrtPriceX96Twap) * uint256(sqrtPriceX96Twap);

        if (isWETHToUSDC) {
            if (wethIsToken0) {
                // token0=WETH, token1=USDC
                // price = USDC_raw / WETH_raw
                // USDC_raw = WETH_raw * price
                return FullMath.mulDiv(amount, priceSquared, 2 ** 192);
            } else {
                // token0=USDC, token1=WETH
                // price = WETH_raw / USDC_raw
                // USDC_raw = WETH_raw / price
                return FullMath.mulDiv(amount, 2 ** 192, priceSquared);
            }
        } else {
            if (wethIsToken0) {
                // token0=WETH, token1=USDC
                // WETH_raw = USDC_raw / price
                return FullMath.mulDiv(amount, 2 ** 192, priceSquared);
            } else {
                // token0=USDC, token1=WETH
                // WETH_raw = USDC_raw * price
                return FullMath.mulDiv(amount, priceSquared, 2 ** 192);
            }
        }
    }

    /// @notice 更新TWAP窗口（仅治理）
    function setTWAPWindow(uint32 _window) external onlyGovernance {
        require(_window >= MIN_TWAP_WINDOW && _window <= MAX_TWAP_WINDOW, "TWAPOracle: invalid window");
        emit TWAPWindowUpdated(twapWindow, _window);
        twapWindow = _window;
    }

    /// @notice 更新治理合约地址
    function setGovernance(address _governance) external onlyOwner {
        emit GovernanceUpdated(governance, _governance);
        governance = _governance;
    }

    /// @notice 确保V3池有足够的观察基数
    function ensureObservationCardinality(uint16 cardinalityNext) external {
        ORACLE_POOL.increaseObservationCardinalityNext(cardinalityNext);
    }
}

src/strategies/AdaptiveRebalanceStrategy.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IRebalanceStrategy, IGovernance} from "../interfaces/ICoreInterfaces.sol";
import {TickMath} from "../libraries/UniswapMath.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {FullMath} from "../libraries/UniswapMath.sol";

/**
 * @title AdaptiveRebalanceStrategy
 * @notice 自适应再平衡策略，对标Gamma Strategies核心算法
 * @dev 根据市场波动率动态调整V2/V3资金分配和V3多区间权重
 */
contract AdaptiveRebalanceStrategy is IRebalanceStrategy, Ownable {
    /// @notice 治理合约
    address public governance;

    uint256 public constant BPS_SCALE = 10000;

    /// @notice WETH/USDC的tick spacing (V3 0.30%池=60, 0.05%池=10)
    int24 public constant TICK_SPACING_LOW = 10;   // 0.05%
    int24 public constant TICK_SPACING_HIGH = 60;  // 0.30%

    /// @notice 波动率阈值
    uint256 public constant LOW_VOL_THRESHOLD = 2000;   // 价格偏离 ≤20%：低波动
    uint256 public constant MID_VOL_THRESHOLD = 5000;   // 20% < 价格偏离 ≤50%：中波动
    // >50% 高波动

    /// @notice 再平衡偏离阈值（basis points），默认5%
    uint256 public rebalanceThresholdBps = 500;

    event GovernanceUpdated(address oldGov, address newGov);
    event ThresholdUpdated(uint256 oldThreshold, uint256 newThreshold);

    modifier onlyGovernance() {
        require(msg.sender == governance || msg.sender == owner(), "Strategy: not authorized");
        _;
    }

    constructor(address _governance) Ownable(msg.sender) {
        governance = _governance;
    }

    /// @inheritdoc IRebalanceStrategy
    /// @dev 根据波动率动态分配：
    /// - 低波动(<20%)：更多资金在V3高费率窄区间赚手续费
    /// - 中波动(20-50%)：均衡分配
    /// - 高波动(>50%)：更多资金在V2全区间抗无常损失
    function calculateAllocation(
        uint256 /* totalWETH */,
        uint256 /* totalUSDC */,
        uint256 volatility
    ) external pure override returns (AllocationWeights memory allocations, V3RangeWeights memory v3Ranges) {
        if (volatility <= LOW_VOL_THRESHOLD) {
            // 低波动：V3为主，窄区间重仓
            allocations = AllocationWeights({
                v2Weight: 1000,        // 10%
                v3LowFeeWeight: 3000,  // 30% (0.05%池，深度好)
                v3HighFeeWeight: 6000  // 60% (0.30%池，手续费高)
            });
            v3Ranges = V3RangeWeights({
                tightWeight: 6000,   // 60%窄区间
                mediumWeight: 3000,  // 30%中区间
                wideWeight: 1000     // 10%宽区间
            });
        } else if (volatility <= MID_VOL_THRESHOLD) {
            // 中波动：均衡配置
            allocations = AllocationWeights({
                v2Weight: 2500,        // 25%
                v3LowFeeWeight: 3000,  // 30%
                v3HighFeeWeight: 4500  // 45%
            });
            v3Ranges = V3RangeWeights({
                tightWeight: 3000,
                mediumWeight: 5000,
                wideWeight: 2000
            });
        } else {
            // 高波动：V2为主，宽区间防守
            allocations = AllocationWeights({
                v2Weight: 5000,        // 50%
                v3LowFeeWeight: 2500,  // 25%
                v3HighFeeWeight: 2500  // 25%
            });
            v3Ranges = V3RangeWeights({
                tightWeight: 1000,
                mediumWeight: 3000,
                wideWeight: 6000
            });
        }
    }

    /// @inheritdoc IRebalanceStrategy
    function getRangeTicks(int24 currentTick)
        external
        pure
        override
        returns (
            int24 tightLower, int24 tightUpper,
            int24 mediumLower, int24 mediumUpper,
            int24 wideLower, int24 wideUpper
        )
    {
        // ±2% 窄区间
        // tick ≈ log(1.0001, price)
        // 2% ≈ log(1.02)/log(1.0001) ≈ 198 ticks
        // 10% ≈ log(1.10)/log(1.0001) ≈ 953 ticks
        // 30% ≈ log(1.30)/log(1.0001) ≈ 2624 ticks

        int24 tightDelta = 198;
        int24 mediumDelta = 953;
        int24 wideDelta = 2624;

        // 使用0.30%池的tick spacing=60对齐
        tightLower = _alignTick(currentTick - tightDelta, TICK_SPACING_HIGH);
        tightUpper = _alignTick(currentTick + tightDelta, TICK_SPACING_HIGH);
        mediumLower = _alignTick(currentTick - mediumDelta, TICK_SPACING_HIGH);
        mediumUpper = _alignTick(currentTick + mediumDelta, TICK_SPACING_HIGH);
        wideLower = _alignTick(currentTick - wideDelta, TICK_SPACING_HIGH);
        wideUpper = _alignTick(currentTick + wideDelta, TICK_SPACING_HIGH);

        // 边界检查
        tightLower = _clampTick(tightLower);
        tightUpper = _clampTick(tightUpper);
        mediumLower = _clampTick(mediumLower);
        mediumUpper = _clampTick(mediumUpper);
        wideLower = _clampTick(wideLower);
        wideUpper = _clampTick(wideUpper);
    }

    /// @inheritdoc IRebalanceStrategy
    function needsRebalance(uint256 currentDeviation) external view override returns (bool) {
        return currentDeviation >= rebalanceThresholdBps;
    }

    /// @notice 设置再平衡阈值
    function setRebalanceThreshold(uint256 _bps) external onlyGovernance {
        require(_bps >= 100 && _bps <= 5000, "Strategy: invalid threshold");
        emit ThresholdUpdated(rebalanceThresholdBps, _bps);
        rebalanceThresholdBps = _bps;
    }

    /// @notice 更新治理地址
    function setGovernance(address _gov) external onlyOwner {
        emit GovernanceUpdated(governance, _gov);
        governance = _gov;
    }

    /// @notice 计算当前价格偏离度（basis points）
    /// @param sqrtPriceX96Current 当前价格 (sqrt(price) * 2^96)
    /// @param sqrtPriceX96Target 目标价格（上次再平衡价格）
    function calculateDeviation(uint160 sqrtPriceX96Current, uint160 sqrtPriceX96Target)
        external
        pure
        returns (uint256)
    {
        return _computePriceDeviationBps(sqrtPriceX96Current, sqrtPriceX96Target);
    }

    /// @notice 估算波动率（基于TWAP与即时价格差异）
    /// @param sqrtPriceX96Spot 即时价格 (sqrt(price) * 2^96)
    /// @param sqrtPriceX96Twap TWAP价格 (sqrt(price) * 2^96)
    function estimateVolatility(uint160 sqrtPriceX96Spot, uint160 sqrtPriceX96Twap)
        external
        pure
        returns (uint256)
    {
        return _computePriceDeviationBps(sqrtPriceX96Spot, sqrtPriceX96Twap);
    }

    // ============ 内部工具 ============

    function _computePriceDeviationBps(uint160 sqrtCurrent, uint160 sqrtTarget) 
        internal 
        pure 
        returns (uint256) 
    {
        if (sqrtTarget == 0) return 0;
        uint256 diff = sqrtCurrent > sqrtTarget
            ? uint256(sqrtCurrent) - uint256(sqrtTarget)
            : uint256(sqrtTarget) - uint256(sqrtCurrent);
        
        uint256 sum = uint256(sqrtCurrent) + uint256(sqrtTarget);

        uint256 temp = FullMath.mulDiv(diff, sum, sqrtTarget);
        return FullMath.mulDiv(temp, BPS_SCALE, sqrtTarget);
    }

    function _alignTick(int24 tick, int24 spacing) internal pure returns (int24) {
        int24 remainder = tick % spacing;
        if (remainder < 0) remainder += spacing;
        return tick - remainder;
    }

    function _clampTick(int24 tick) internal pure returns (int24) {
        if (tick < TickMath.MIN_TICK) return TickMath.MIN_TICK;
        if (tick > TickMath.MAX_TICK) return TickMath.MAX_TICK;
        return tick;
    }
}

src/adapters/UniswapV2Adapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IUniswapV2Router02, IUniswapV2Pair, IUniswapV2Factory} from "../interfaces/IUniswapV2.sol";
import {ILPAdapter} from "../interfaces/ILPAdapter.sol";
import {FullMath} from "../libraries/UniswapMath.sol";

/**
 * @title UniswapV2Adapter
 * @notice Uniswap V2流动性适配器
 * @dev 通过V2 Router管理LP，金库持有LP token
 */
contract UniswapV2Adapter is ILPAdapter, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant BPS_SCALE = 10000;
    uint256 public maxSlippageBps = 100; // 默认1%

    /// @notice V2 Router
    IUniswapV2Router02 public immutable ROUTER;

    /// @notice V2 Pair
    IUniswapV2Pair public immutable PAIR;

    /// @notice V2 Factory
    IUniswapV2Factory public immutable FACTORY;

    /// @notice 金库地址（唯一有权调用者）
    address public immutable VAULT;

    /// @notice token0
    address public immutable override TOKEN0;

    /// @notice token1
    address public immutable override TOKEN1;

    /// @notice 适配器类型
    AdapterType public constant override adapterType = AdapterType.UNISWAP_V2;

    /// @notice 唯一仓位ID（V2只有一个全区间仓位）
    bytes32 public constant POSITION_ID = keccak256("UniswapV2Adapter.POSITION");

    /// @notice dust阈值，低于此值的剩余代币视为灰尘
    uint256 public constant DUST_THRESHOLD = 1000;

    event LiquidityAdded(uint256 amount0, uint256 amount1, uint256 liquidity);
    event LiquidityRemoved(uint256 amount0, uint256 amount1, uint256 liquidity);
    event FeesCollected(uint256 fees0, uint256 fees1);

    modifier onlyVault() {
        require(msg.sender == VAULT, "V2Adapter: not vault");
        _;
    }

    constructor(
        address _router,
        address _vault,
        address _token0,
        address _token1
    ) {
        require(_router != address(0), "V2Adapter: zero router");
        require(_vault != address(0), "V2Adapter: zero vault");
        require(_token0 != address(0) && _token1 != address(0), "V2Adapter: zero tokens");

        ROUTER = IUniswapV2Router02(_router);
        VAULT = _vault;
        FACTORY = IUniswapV2Factory(ROUTER.factory());
        TOKEN0 = _token0;
        TOKEN1 = _token1;

        // 获取或创建pair
        address pairAddress = FACTORY.getPair(_token0, _token1);
        if (pairAddress == address(0)) {
            pairAddress = FACTORY.createPair(_token0, _token1);
        }
        PAIR = IUniswapV2Pair(pairAddress);

        // 授权Router无限额度
        IERC20(_token0).forceApprove(_router, type(uint256).max);
        IERC20(_token1).forceApprove(_router, type(uint256).max);
        IERC20(pairAddress).forceApprove(_router, type(uint256).max);
    }

    /// @inheritdoc ILPAdapter
    function addLiquidity(
        uint256 amount0Desired,
        uint256 amount1Desired,
        uint256 amount0Min,
        uint256 amount1Min,
        bytes calldata /* data */
    ) external onlyVault nonReentrant returns (uint256 amount0, uint256 amount1, bytes32 liquidityId) {
        require(amount0Desired > 0 || amount1Desired > 0, "V2Adapter: zero amounts");

        // 从金库转入代币
        if (amount0Desired > 0) {
            IERC20(TOKEN0).safeTransferFrom(VAULT, address(this), amount0Desired);
        }
        if (amount1Desired > 0) {
            IERC20(TOKEN1).safeTransferFrom(VAULT, address(this), amount1Desired);
        }

        // 添加流动性
        (amount0, amount1, ) = ROUTER.addLiquidity(
            TOKEN0,
            TOKEN1,
            amount0Desired,
            amount1Desired,
            amount0Min,
            amount1Min,
            address(this),
            block.timestamp + 600
        );

        uint256 bal0 = IERC20(TOKEN0).balanceOf(address(this));
        uint256 bal1 = IERC20(TOKEN1).balanceOf(address(this));
        if (bal0 > 0) IERC20(TOKEN0).safeTransfer(VAULT, bal0);
        if (bal1 > 0) IERC20(TOKEN1).safeTransfer(VAULT, bal1);

        liquidityId = POSITION_ID;
        emit LiquidityAdded(amount0, amount1, PAIR.balanceOf(address(this)));
    }

    /// @inheritdoc ILPAdapter
    function removeLiquidity(
        bytes32 /* liquidityId */,
        uint128 liquidity,
        uint256 amount0Min,
        uint256 amount1Min
    ) external onlyVault nonReentrant returns (uint256 amount0, uint256 amount1) {
        require(liquidity > 0, "V2Adapter: zero liquidity");
        require(liquidity <= PAIR.balanceOf(address(this)), "V2Adapter: insufficient LP");

        (amount0, amount1) = ROUTER.removeLiquidity(
            TOKEN0,
            TOKEN1,
            liquidity,
            amount0Min,
            amount1Min,
            VAULT,  // 直接转给金库
            block.timestamp + 600
        );

        emit LiquidityRemoved(amount0, amount1, liquidity);
    }

    /// @inheritdoc ILPAdapter
    /// @dev UniswapV2协议限制：手续费内嵌在LP代币价值内部，
    /// 无法在不销毁流动性的前提下单独提取手续费。
    /// 手续费将在removeLiquidity赎回流动性时随同本金一起返回Vault。
    function collectFees(bytes32 /* liquidityId */)
        external
        onlyVault
        nonReentrant
        returns (uint256 fees0, uint256 fees1)
    {
        fees0 = 0;
        fees1 = 0;
        emit FeesCollected(0, 0);
    }

    /// @inheritdoc ILPAdapter
    function getTotalAssets() external view override returns (AdapterAssets memory assets) {
        return _getTotalAssets();
    }

    /// @inheritdoc ILPAdapter
    function getPositionAssets(bytes32 /* liquidityId */)
        external
        view
        override
        returns (AdapterAssets memory assets)
    {
        return _getTotalAssets();
    }

    /// @inheritdoc ILPAdapter
    function getActivePositions() external pure override returns (bytes32[] memory positions) {
        positions = new bytes32[](1);
        positions[0] = POSITION_ID;
    }

    /// @notice 获取当前LP余额
    function getLpBalance() external view override returns (uint256) {
        return PAIR.balanceOf(address(this));
    }

    /// @inheritdoc ILPAdapter
    function withdrawAll() external onlyVault nonReentrant {
        uint256 lpBalance = PAIR.balanceOf(address(this));

        (uint112 reserve0, uint112 reserve1, ) = PAIR.getReserves();
        uint256 totalSupply = PAIR.totalSupply();

        uint256 slippageMin = BPS_SCALE - maxSlippageBps;

        uint256 expected0 = FullMath.mulDiv(uint256(reserve0), lpBalance, totalSupply);
        uint256 expected1 = FullMath.mulDiv(uint256(reserve1), lpBalance, totalSupply);

        // 扣除滑点下限
        uint256 amount0Min = FullMath.mulDiv(expected0, slippageMin, BPS_SCALE);
        uint256 amount1Min = FullMath.mulDiv(expected1, slippageMin, BPS_SCALE);

        if (lpBalance > 0) {
            ROUTER.removeLiquidity(
                TOKEN0,
                TOKEN1,
                lpBalance,
                amount0Min, 
                amount1Min,
                VAULT,
                block.timestamp + 600
            );
        }
        // 转移剩余dust
        uint256 bal0 = IERC20(TOKEN0).balanceOf(address(this));
        uint256 bal1 = IERC20(TOKEN1).balanceOf(address(this));
        if (bal0 > 0) IERC20(TOKEN0).safeTransfer(VAULT, bal0);
        if (bal1 > 0) IERC20(TOKEN1).safeTransfer(VAULT, bal1);
    }

    function _getTotalAssets() internal view returns (AdapterAssets memory assets) {
        uint256 lpBalance = PAIR.balanceOf(address(this));
        if (lpBalance == 0) {
            assets.amount0 = IERC20(TOKEN0).balanceOf(address(this));
            assets.amount1 = IERC20(TOKEN1).balanceOf(address(this));
            return assets;
        }

        (uint112 reserve0, uint112 reserve1, ) = PAIR.getReserves();
        uint256 totalSupply = PAIR.totalSupply();

        // LP对应的资产
        assets.amount0 = FullMath.mulDiv(lpBalance, uint256(reserve0), totalSupply);
        assets.amount1 = FullMath.mulDiv(lpBalance, uint256(reserve1), totalSupply);

        // 加上合约上未投资的代币
        assets.amount0 += IERC20(TOKEN0).balanceOf(address(this));
        assets.amount1 += IERC20(TOKEN1).balanceOf(address(this));

        // V2手续费已包含在LP价值中，fees0/fees1设为0
        assets.fees0 = 0;
        assets.fees1 = 0;
    }
}

