    }

    function _investV3TightWeighted(
        ILPAdapter adapter,
        uint256 totalWETH,
        uint256 totalUSDC,
        int24 tickLower,
        int24 tickUpper,
        uint256 weight,
        uint256 totalWeight
    ) internal {
